/**
 * خدمة إدارة عمليات التحويل والسحب بين المحافظ وصندوق النقدية
 * 
 * هذه الخدمة تتعامل مع:
 * 1. التحويل: خصم من إجمالي المحافظ وإضافة لصندوق النقدية
 * 2. السحب: خصم من صندوق النقدية وإضافة لإجمالي المحافظ
 * 3. التحقق من الحدود اليومية والشهرية لكل محفظة
 */

import { walletDailyLimitsService } from './walletDailyLimitsService';

export interface WalletBalance {
  [walletId: string]: number;
}

export interface TransactionResult {
  success: boolean;
  newCashBalance: number;
  newWalletBalances: WalletBalance;
  message: string;
  error?: string;
}

export interface TransferOperation {
  amount: number;
  currentCashBalance: number;
  currentWalletBalances: WalletBalance;
  wallets: Array<{ id: string; name: string; isDefault?: boolean }>;
  selectedWalletId?: string; // معرف المحفظة المحددة للعملية
  // وضع سريع: تخطي فحص الحدود البعيد وجعل تحديث الاستخدام غير متزامن
  skipRemoteLimitsCheck?: boolean;
  nonBlockingUsageUpdate?: boolean;
}

export interface WithdrawOperation {
  amount: number;
  currentCashBalance: number;
  currentWalletBalances: WalletBalance;
  wallets: Array<{ id: string; name: string; isDefault?: boolean }>;
  selectedWalletId?: string; // معرف المحفظة المحددة للعملية
  // وضع سريع: تخطي فحص الحدود البعيد وجعل تحديث الاستخدام غير متزامن
  skipRemoteLimitsCheck?: boolean;
  nonBlockingUsageUpdate?: boolean;
}

export class WalletCashService {
  
  /**
   * عملية التحويل: خصم من إجمالي المحافظ وإضافة لصندوق النقدية
   * مع التحقق من الحدود اليومية والشهرية
   * @param operation بيانات عملية التحويل
   * @returns نتيجة العملية
   */
  static async processTransfer(operation: TransferOperation): Promise<TransactionResult> {
    const { amount, currentCashBalance, currentWalletBalances, wallets, selectedWalletId } = operation;
    
    // التحقق من صحة المبلغ
    if (amount <= 0) {
      return {
        success: false,
        newCashBalance: currentCashBalance,
        newWalletBalances: currentWalletBalances,
        message: "المبلغ يجب أن يكون أكبر من الصفر",
        error: "INVALID_AMOUNT"
      };
    }

    // التحقق من الحدود اليومية والشهرية للمحفظة المحددة
    if (selectedWalletId && !operation.skipRemoteLimitsCheck) {
      try {
        const limitCheck = await walletDailyLimitsService.canPerformOperation(selectedWalletId, amount, 'transfer');
        if (!limitCheck.canPerform) {
          return {
            success: false,
            newCashBalance: currentCashBalance,
            newWalletBalances: currentWalletBalances,
            message: limitCheck.message || "تم تجاوز الحد الأقصى",
            error: "LIMIT_EXCEEDED"
          };
        }
      } catch (error) {
        console.error('خطأ في التحقق من حدود التحويل:', error);
        return {
          success: false,
          newCashBalance: currentCashBalance,
          newWalletBalances: currentWalletBalances,
          message: "خطأ في التحقق من حدود التحويل",
          error: "LIMIT_CHECK_ERROR"
        };
      }
    }
    
    // التحقق من صحة المبلغ
    if (amount <= 0) {
      return {
        success: false,
        newCashBalance: currentCashBalance,
        newWalletBalances: currentWalletBalances,
        message: "المبلغ يجب أن يكون أكبر من الصفر",
        error: "INVALID_AMOUNT"
      };
    }

    // التحقق المسبق من توفر رصيد كافي قبل أي خصم
    if (selectedWalletId) {
      const available = Math.max(currentWalletBalances[selectedWalletId] || 0, 0);
      if (available < amount) {
        const target = wallets.find(w => w.id === selectedWalletId);
        return {
          success: false,
          newCashBalance: currentCashBalance,
          newWalletBalances: currentWalletBalances,
          message: `رصيد غير كافي في المحفظة${target ? ` ${target.name}` : ''}. المتاح: ${available} جنيه، المطلوب: ${amount} جنيه`,
          error: "INSUFFICIENT_WALLET_BALANCE"
        };
      }
    } else {
      const totalAvailable = WalletCashService.calculateTotalWalletBalance(currentWalletBalances);
      if (totalAvailable < amount) {
        return {
          success: false,
          newCashBalance: currentCashBalance,
          newWalletBalances: currentWalletBalances,
          message: `رصيد غير كافي في المحافظ. الرصيد المتاح: ${totalAvailable} جنيه، المبلغ المطلوب: ${amount} جنيه`,
          error: "INSUFFICIENT_WALLET_BALANCE"
        };
      }
    }

    // إنشاء نسخة من أرصدة المحافظ للتعديل عليها
    const newWalletBalances = { ...currentWalletBalances };

    if (selectedWalletId) {
      const currentBalance = newWalletBalances[selectedWalletId] || 0;
      newWalletBalances[selectedWalletId] = currentBalance - amount;
    } else {
      let remainingAmount = amount;
      for (const wallet of wallets) {
        if (remainingAmount <= 0) break;
        const currentBalance = Math.max(newWalletBalances[wallet.id] || 0, 0);
        const deductAmount = Math.min(currentBalance, remainingAmount);
        if (deductAmount > 0) {
          newWalletBalances[wallet.id] = (newWalletBalances[wallet.id] || 0) - deductAmount;
          remainingAmount -= deductAmount;
        }
      }
      // لا خصم سالب: تم التحقق مسبقاً أن الإجمالي كافٍ
    }

    const newCashBalance = currentCashBalance + amount;

    

    // تحديد رسالة التحذير إذا أصبح رصيد المحفظة المختارة سالباً
    let message = "تم التحويل بنجاح";
    if (selectedWalletId) {
      const afterBalance = newWalletBalances[selectedWalletId] || 0;
      if (afterBalance < 0) {
        message = `تم التحويل بنجاح مع تحذير: رصيد محفظة ${selectedWalletId} أصبح ${afterBalance} جنيه.`;
      }
    }

    return {
      success: true,
      newCashBalance,
      newWalletBalances,
      message
    };
  }

  /**
   * عملية الإيداع: خصم من إجمالي المحافظ وإضافة لصندوق النقدية
   * @param operation بيانات عملية الإيداع
   * @returns نتيجة العملية
   */
  static processDeposit(operation: TransferOperation): TransactionResult {
    const { amount, currentCashBalance, currentWalletBalances, wallets } = operation;
    
    // التحقق من صحة المبلغ
    if (amount <= 0) {
      return {
        success: false,
        newCashBalance: currentCashBalance,
        newWalletBalances: currentWalletBalances,
        message: "المبلغ يجب أن يكون أكبر من الصفر",
        error: "INVALID_AMOUNT"
      };
    }

    // التحقق من وجود رصيد كافي في المحافظ
    const totalWalletBalance = this.calculateTotalWalletBalance(currentWalletBalances);
    if (totalWalletBalance < amount) {
      return {
        success: false,
        newCashBalance: currentCashBalance,
        newWalletBalances: currentWalletBalances,
        message: `رصيد غير كافي في المحافظ. الرصيد المتاح: ${totalWalletBalance} جنيه، المبلغ المطلوب: ${amount} جنيه`,
        error: "INSUFFICIENT_WALLET_BALANCE"
      };
    }

    // إضافة المبلغ لصندوق النقدية
    const newCashBalance = currentCashBalance + amount;

    // خصم المبلغ من المحافظ
    const newWalletBalances = { ...currentWalletBalances };
    let remainingAmount = amount;

    // البحث عن المحفظة الافتراضية أولاً
    const defaultWallet = wallets.find(w => w.isDefault);
    
    if (defaultWallet && newWalletBalances[defaultWallet.id] >= remainingAmount) {
      // إذا كانت المحفظة الافتراضية تحتوي على رصيد كافي
      newWalletBalances[defaultWallet.id] -= remainingAmount;
      remainingAmount = 0;
    } else {
      // خصم من جميع المحافظ بالتناسب
      for (const wallet of wallets) {
        if (remainingAmount <= 0) break;
        
        const balance = newWalletBalances[wallet.id] || 0;
        if (balance > 0) {
          const deductAmount = Math.min(balance, remainingAmount);
          newWalletBalances[wallet.id] = balance - deductAmount;
          remainingAmount -= deductAmount;
        }
      }
    }

    const message = remainingAmount > 0 
      ? `تم الإيداع جزئياً. تم إيداع ${amount - remainingAmount} جنيه في صندوق النقدية`
      : `تم الإيداع بنجاح. تم إضافة ${amount} جنيه إلى صندوق النقدية`;

    return {
      success: true,
      newCashBalance,
      newWalletBalances,
      message
    };
  }

  /**
   * عملية السحب: خصم من صندوق النقدية وإضافة لإجمالي المحافظ
   * @param operation بيانات عملية السحب
   * @returns نتيجة العملية
   */
  static async processWithdraw(operation: WithdrawOperation): Promise<TransactionResult> {
    const { amount, currentCashBalance, currentWalletBalances, wallets, selectedWalletId } = operation;
    
    // التحقق من صحة المبلغ
    if (amount <= 0) {
      return {
        success: false,
        newCashBalance: currentCashBalance,
        newWalletBalances: currentWalletBalances,
        message: "المبلغ يجب أن يكون أكبر من الصفر",
        error: "INVALID_AMOUNT"
      };
    }

    // التحقق من الحدود اليومية والشهرية للمحفظة المحددة
    if (selectedWalletId && !operation.skipRemoteLimitsCheck) {
      try {
        const limitCheck = await walletDailyLimitsService.canPerformOperation(selectedWalletId, amount, 'withdraw');
        if (!limitCheck.canPerform) {
          return {
            success: false,
            newCashBalance: currentCashBalance,
            newWalletBalances: currentWalletBalances,
            message: limitCheck.message || "تم تجاوز الحد الأقصى",
            error: "LIMIT_EXCEEDED"
          };
        }
      } catch (error) {
        console.error('خطأ في التحقق من حدود السحب:', error);
        return {
          success: false,
          newCashBalance: currentCashBalance,
          newWalletBalances: currentWalletBalances,
          message: "خطأ في التحقق من حدود السحب",
          error: "LIMIT_CHECK_ERROR"
        };
      }
    }

    // التحقق من وجود رصيد كافي في صندوق النقدية
    if (currentCashBalance < amount) {
      return {
        success: false,
        newCashBalance: currentCashBalance,
        newWalletBalances: currentWalletBalances,
        message: `رصيد غير كافي في صندوق النقدية. الرصيد المتاح: ${currentCashBalance} جنيه، المبلغ المطلوب: ${amount} جنيه`,
        error: "INSUFFICIENT_CASH_BALANCE"
      };
    }

    // خصم المبلغ من صندوق النقدية
    const newCashBalance = Math.round(currentCashBalance - amount);

    // إضافغصم المبلغ من صندوق النقدية
    const newWalletBalances = { ...currentWalletBalances };
    const targetWallet = selectedWalletId ? wallets.find(w => w.id === selectedWalletId) : (wallets.find(w => w.isDefault) || wallets[0]);
    
    if (targetWallet) {
      const currentBalance = newWalletBalances[targetWallet.id] || 0;
      newWalletBalances[targetWallet.id] = currentBalance + amount;
    } else {
      return {
        success: false,
        newCashBalance: currentCashBalance,
        newWalletBalances: currentWalletBalances,
        message: "لا توجد محافظ متاحة لإضافة المبلغ إليها",
        error: "NO_WALLETS_AVAILABLE"
      };
    }

    

    return {
      success: true,
      newCashBalance,
      newWalletBalances,
      message: `تم السحب بنجاح. تم إضافة ${amount} جنيه إلى محفظة ${targetWallet?.name || ''}`
    };
  }

  /**
   * التحقق من صحة البيانات قبل إجراء العملية
   * @param amount المبلغ
   * @param wallets قائمة المحافظ
   * @returns true إذا كانت البيانات صحيحة
   */
  static validateOperation(amount: number, wallets: Array<{ id: string; name: string }>): { valid: boolean; error?: string } {
    if (amount <= 0) {
      return { valid: false, error: "المبلغ يجب أن يكون أكبر من الصفر" };
    }

    if (!wallets || wallets.length === 0) {
      return { valid: false, error: "لا توجد محافظ متاحة" };
    }

    return { valid: true };
  }

  /**
   * حساب إجمالي أرصدة المحافظ
   * @param walletBalances أرصدة المحافظ
   * @returns إجمالي الأرصدة
   */
  static calculateTotalWalletBalance(walletBalances: WalletBalance): number {
    return Object.values(walletBalances).reduce((total, balance) => total + Math.max(balance, 0), 0);
  }

  /**
   * دالة خصم من إجمالي المحافظ وإضافة لصندوق النقدية (التحويل)
   * @param amount المبلغ المراد تحويله
   * @param currentCashBalance الرصيد الحالي لصندوق النقدية
   * @param currentWalletBalances الأرصدة الحالية للمحافظ
   * @param wallets قائمة المحافظ
   * @returns نتيجة العملية
   */
  static deductFromWalletsAddToCash(
    amount: number,
    currentCashBalance: number,
    currentWalletBalances: WalletBalance,
    wallets: Array<{ id: string; name: string; isDefault?: boolean }>
  ): TransactionResult {
    return this.processTransfer({
      amount,
      currentCashBalance,
      currentWalletBalances,
      wallets
    });
  }

  /**
   * دالة خصم من إجمالي المحافظ وإضافة لصندوق النقدية (الإيداع)
   * @param amount المبلغ المراد إيداعه
   * @param currentCashBalance الرصيد الحالي لصندوق النقدية
   * @param currentWalletBalances الأرصدة الحالية للمحافظ
   * @param wallets قائمة المحافظ
   * @returns نتيجة العملية
   */
  static deductFromWalletsAddToCashDeposit(
    amount: number,
    currentCashBalance: number,
    currentWalletBalances: WalletBalance,
    wallets: Array<{ id: string; name: string; isDefault?: boolean }>
  ): TransactionResult {
    return this.processDeposit({
      amount,
      currentCashBalance,
      currentWalletBalances,
      wallets
    });
  }

  /**
   * دالة خصم من صندوق النقدية وإضافة لإجمالي المحافظ (السحب)
   * @param amount المبلغ المراد سحبه
   * @param currentCashBalance الرصيد الحالي لصندوق النقدية
   * @param currentWalletBalances الأرصدة الحالية للمحافظ
   * @param wallets قائمة المحافظ
   * @returns نتيجة العملية
   */
  static deductFromCashAddToWallets(
    amount: number,
    currentCashBalance: number,
    currentWalletBalances: WalletBalance,
    wallets: Array<{ id: string; name: string; isDefault?: boolean }>
  ): TransactionResult {
    return this.processWithdraw({
      amount,
      currentCashBalance,
      currentWalletBalances,
      wallets
    });
  }

  /**
   * دالة مساعدة لتطبيق نتائج العملية على البيانات الفعلية
   * @param result نتيجة العملية
   * @param updateCashBalance دالة تحديث رصيد النقدية
   * @param updateWalletBalances دالة تحديث أرصدة المحافظ
   */
  static applyTransactionResult(
    result: TransactionResult,
    updateCashBalance: (newBalance: number) => void,
    updateWalletBalances: (newBalances: WalletBalance) => void
  ): void {
    if (result.success) {
      updateCashBalance(result.newCashBalance);
      updateWalletBalances(result.newWalletBalances);
    }
  }

  /**
   * دالة للتحقق من إمكانية إجراء العملية
   * @param amount المبلغ
   * @param operationType نوع العملية (transfer أو withdraw أو deposit)
   * @param currentCashBalance الرصيد الحالي لصندوق النقدية
   * @param currentWalletBalances الأرصدة الحالية للمحافظ
   * @returns معلومات التحقق
   */
  static validateTransaction(
    amount: number,
    operationType: 'transfer' | 'withdraw' | 'deposit',
    currentCashBalance: number,
    currentWalletBalances: WalletBalance
  ): { isValid: boolean; warning?: string; error?: string } {
    if (amount <= 0) {
      return {
        isValid: false,
        error: "المبلغ يجب أن يكون أكبر من الصفر"
      };
    }

    if (operationType === 'transfer') {
      const totalWalletBalance = this.calculateTotalWalletBalance(currentWalletBalances);
      if (totalWalletBalance < amount) {
        return {
          isValid: false,
          error: `الرصيد المتاح في المحافظ (${totalWalletBalance} جنيه) غير كافي للمبلغ المطلوب (${amount} جنيه)`
        };
      }
    } else if (operationType === 'withdraw') {
      if (currentCashBalance < amount) {
        return {
          isValid: false,
          error: `الرصيد المتاح في صندوق النقدية (${currentCashBalance} جنيه) غير كافي للمبلغ المطلوب (${amount} جنيه)`
        };
      }
    } else if (operationType === 'deposit') {
      const totalWalletBalance = this.calculateTotalWalletBalance(currentWalletBalances);
      if (totalWalletBalance < amount) {
        return {
          isValid: false,
          error: `الرصيد المتاح في المحافظ (${totalWalletBalance} جنيه) غير كافي للمبلغ المطلوب (${amount} جنيه)`
        };
      }
    }

    return { isValid: true };
  }

  /**
   * الحصول على تفاصيل توزيع الخصم على المحافظ (للمعاينة فقط)
   * @param amount المبلغ المراد خصمه
   * @param currentWalletBalances أرصدة المحافظ الحالية
   * @param wallets قائمة المحافظ
   * @returns تفاصيل التوزيع
   */
  static getDeductionPreview(
    amount: number, 
    currentWalletBalances: WalletBalance, 
    wallets: Array<{ id: string; name: string; isDefault?: boolean }>
  ): Array<{ walletId: string; walletName: string; currentBalance: number; deductedAmount: number; newBalance: number }> {
    const preview: Array<{ walletId: string; walletName: string; currentBalance: number; deductedAmount: number; newBalance: number }> = [];
    let remainingAmount = amount;

    // خصم من المحافظ بالترتيب
    for (const wallet of wallets) {
      if (remainingAmount <= 0) break;
      
      const currentBalance = currentWalletBalances[wallet.id] || 0;
      const deductAmount = Math.min(Math.max(currentBalance, 0), remainingAmount);
      
      if (deductAmount > 0) {
        preview.push({
          walletId: wallet.id,
          walletName: wallet.name,
          currentBalance,
          deductedAmount: deductAmount,
          newBalance: currentBalance - deductAmount
        });
        remainingAmount -= deductAmount;
      }
    }

    // لا نخصم سالب عند عدم كفاية الرصيد

    return preview;
  }
}

export default WalletCashService;
